export const part = 1;
export const html = "<p class=\"lead\"><code>gh</code> برنامهٔ رسمی GitHub برای ترمینال است. با آن می‌توانی بدون باز کردن مرورگر ریپو بسازی، PR باز کنی، و وضعیت Actions را ببینی.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>با <code>gh</code> چرخهٔ کامل PR را طی کنی</li>\n<li>Issue و Release بسازی</li>\n<li>خروجی را با <code>--json</code> و <code>jq</code> اسکریپت کنی</li>\n<li>از <code>gh api</code> برای چیزهایی که فرمان آماده ندارند استفاده کنی</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">⚙️ ورود و پیش‌فرض</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">auth و تنظیم</span></div><pre>gh<span style=\"color: #F8F8F2\"> </span>auth<span style=\"color: #F8F8F2\"> </span>login\ngh<span style=\"color: #F8F8F2\"> </span>auth<span style=\"color: #F8F8F2\"> </span>setup-git<span style=\"color: #F8F8F2\">              </span><span style=\"color: #959077\"># credential helper</span>\ngh<span style=\"color: #F8F8F2\"> </span>config<span style=\"color: #F8F8F2\"> set </span>editor<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;code --wait&quot;</span>\ngh<span style=\"color: #F8F8F2\"> alias set </span>pv<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;pr view --web&quot;</span>\n</pre></div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🔁 چرخهٔ PR</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">روزانه</span></div><pre>gh<span style=\"color: #F8F8F2\"> </span>pr<span style=\"color: #F8F8F2\"> </span>checkout<span style=\"color: #F8F8F2\"> </span><span style=\"color: #AE81FF\">42</span>\ngh<span style=\"color: #F8F8F2\"> </span>pr<span style=\"color: #F8F8F2\"> </span>status\ngh<span style=\"color: #F8F8F2\"> </span>pr<span style=\"color: #F8F8F2\"> </span>checks\ngh<span style=\"color: #F8F8F2\"> </span>pr<span style=\"color: #F8F8F2\"> </span>diff\ngh<span style=\"color: #F8F8F2\"> </span>pr<span style=\"color: #F8F8F2\"> </span>comment<span style=\"color: #F8F8F2\"> </span>--body<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;nit: نام تابع را rotateTokens بگذار&quot;</span>\ngh<span style=\"color: #F8F8F2\"> </span>pr<span style=\"color: #F8F8F2\"> </span>merge<span style=\"color: #F8F8F2\"> </span><span style=\"color: #AE81FF\">42</span><span style=\"color: #F8F8F2\"> </span>--squash<span style=\"color: #F8F8F2\"> </span>--delete-branch\ngh<span style=\"color: #F8F8F2\"> </span>pr<span style=\"color: #F8F8F2\"> </span>list<span style=\"color: #F8F8F2\"> </span>--author<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;@me&quot;</span><span style=\"color: #F8F8F2\"> </span>--state<span style=\"color: #F8F8F2\"> </span>open\n</pre></div>\n<p><code>gh pr create --fill</code> از عنوان کامیت‌ها بدنه می‌سازد — بعد دستی ویرایش کن.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🎫 Issue و پروژه</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">Issue</span></div><pre>gh<span style=\"color: #F8F8F2\"> </span>issue<span style=\"color: #F8F8F2\"> </span>create<span style=\"color: #F8F8F2\"> </span>-t<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;PDF build fails on Windows&quot;</span><span style=\"color: #F8F8F2\"> </span>-b<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;steps...&quot;</span><span style=\"color: #F8F8F2\"> </span>-l<span style=\"color: #F8F8F2\"> </span>bug\ngh<span style=\"color: #F8F8F2\"> </span>issue<span style=\"color: #F8F8F2\"> </span>develop<span style=\"color: #F8F8F2\"> </span><span style=\"color: #AE81FF\">18</span><span style=\"color: #F8F8F2\"> </span>--checkout<span style=\"color: #F8F8F2\">    </span><span style=\"color: #959077\"># شاخه از روی issue</span>\ngh<span style=\"color: #F8F8F2\"> </span>issue<span style=\"color: #F8F8F2\"> </span>close<span style=\"color: #F8F8F2\"> </span><span style=\"color: #AE81FF\">18</span><span style=\"color: #F8F8F2\"> </span>--reason<span style=\"color: #F8F8F2\"> </span>completed\n</pre></div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🚀 Release و Actions</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">عرضه و CI</span></div><pre>gh<span style=\"color: #F8F8F2\"> </span>release<span style=\"color: #F8F8F2\"> </span>create<span style=\"color: #F8F8F2\"> </span>v1.0.0<span style=\"color: #F8F8F2\"> </span>--generate-notes<span style=\"color: #F8F8F2\"> </span>--title<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;v1.0.0&quot;</span>\ngh<span style=\"color: #F8F8F2\"> </span>run<span style=\"color: #F8F8F2\"> </span>list<span style=\"color: #F8F8F2\"> </span>--branch<span style=\"color: #F8F8F2\"> </span>main\ngh<span style=\"color: #F8F8F2\"> </span>run<span style=\"color: #F8F8F2\"> </span>watch\ngh<span style=\"color: #F8F8F2\"> </span>run<span style=\"color: #F8F8F2\"> </span>view<span style=\"color: #F8F8F2\"> </span>--log-failed\n</pre></div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🧪 اسکریپت‌سازی</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">JSON</span></div><pre>gh<span style=\"color: #F8F8F2\"> </span>pr<span style=\"color: #F8F8F2\"> </span>list<span style=\"color: #F8F8F2\"> </span>--json<span style=\"color: #F8F8F2\"> </span>number,title,reviewDecision,statusCheckRollup\ngh<span style=\"color: #F8F8F2\"> </span>api<span style=\"color: #F8F8F2\"> </span>repos/:owner/:repo/actions/runs<span style=\"color: #F8F8F2\"> </span>--jq<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&#39;.workflow_runs[0].html_url&#39;</span>\ngh<span style=\"color: #F8F8F2\"> </span>api<span style=\"color: #F8F8F2\"> </span>-X<span style=\"color: #F8F8F2\"> </span>PUT<span style=\"color: #F8F8F2\"> </span>repos/:owner/:repo/actions/permissions<span style=\"color: #F8F8F2\"> </span>-f<span style=\"color: #F8F8F2\"> enabled</span><span style=\"color: #FF4689\">=</span><span style=\"color: #F8F8F2\">true</span>\n</pre></div>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">Codespaces و CLI</div>\n<p><code>gh cs create</code> / <code>gh cs ssh</code> محیط ابری را بدون UI می‌سازد — مفید وقتی لپ‌تاپ ضعیف است یا از موبایل فقط ترمینال داری.</p>\n</div>\n<p>در VS Code ترمینال یکپارچه همان <code>gh</code> را اجرا می‌کند؛ افزونهٔ PR و CLI مکمل‌اند نه رقیب.</p>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Junior — gh جایگزین git است؟</strong> خیر. <code>git</code> تاریخچه؛ <code>gh</code> API گیت‌هاب.</p>\n<p><strong>Mid — --json چرا مهم است؟</strong> خروجی انسانی ناپایدار است؛ JSON برای CI پایدار است.</p>\n<p><strong>Senior — app token در برابر user token؟</strong> GitHub App برای ربات و Actions امن‌تر است؛ least privilege و audit بهتر.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ چک‌لیست فهم</span></span></h2>\n<div class=\"keep-block\"><div class=\"checklist\">\n<ul>\n<li>PR را بدون مرورگر merge کرده‌ای</li>\n<li><code>gh run watch</code> را دیده‌ای</li>\n<li>یک <code>alias</code> شخصی ساخته‌ای</li>\n</ul>\n</div><p><strong>فصل بعد:</strong> Issues، Projects و Discussions.</p></div>";
export default { n, num, title, label, part, html };
